class Solution {
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr;
        while (head) {
            ListNode* next = head->next;
            head->next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }
public:
    ListNode* doubleIt(ListNode* head) {
        head = reverseList(head);
        ListNode* cur = head;
        ListNode* prev = nullptr;
        int carry = 0;
        while (cur) {
            int total = cur->val * 2 + carry;
            cur->val = total % 10;
            carry = total / 10;
            prev = cur;
            cur = cur->next;
        }
        if (carry) {
            prev->next = new ListNode(carry);
        }
        return reverseList(head);
    }
};
